      host: url.host,
      path: url.pathname
        .split("/")
        .filter((segment, index) => !(index === 0 && segment === "")),
      query: url.search.startsWith("?") ? url.search.slice(1) : url.search,
      fragment: url.hash.startsWith("#") ? url.hash.slice(1) : url.hash,
